            int aid=f.load(a,"Alice",Set.of("steam:76561198000000000"));f.load(b,"Bob",Set.of());
            f.commandUntil(b,"/infblocks all on","permission");assertFalse(f.match().teamRules().infinite(2));
            f.commandUntil(a,"/infblocks all on","Infinite blocks on for Blue, Green");f.loop.until(()->b.packets.stream().filter(SimplePackets.TeamInfiniteBlocks.class::isInstance).count()>=2);assertTrue(f.match().teamRules().infinite(2));assertTrue(f.match().teamRules().infinite(3));
            f.commandUntil(a,"/lockscore Blue on","Score lock on for Blue");var team=f.match().teams().getFirst();team.addScore(100);assertEquals(0,team.score);team.score=7;
            f.load(late,"Carol",Set.of());var state=late.packets.stream().filter(StateData.class::isInstance).map(StateData.class::cast).findFirst().orElseThrow();assertTrue(state.team1().infiniteBlocks());assertTrue(state.team1().lockedScore());f.loop.until(()->late.has(81)&&late.packets.stream().filter(SimplePackets.TeamInfiniteBlocks.class::isInstance).count()>=2);
            f.commandUntil(a,"/lockscore 1 off","Score lock off for Blue");f.loop.until(()->a.packets.stream().anyMatch(v->v instanceof SimplePackets.SetScore row&&row.typeValue()==0&&row.reason()==0&&row.specifier()==2&&row.value()==7));team.addScore(1);assertEquals(8,team.score);
            f.commandUntil(a,"/infiniteblocks Green off","Infinite blocks off for Green");f.commandUntil(a,"/infiniteblocks all","Blue: on, Green: off");f.commandUntil(a,"/lockscore all maybe","Usage: /lockscore");
