    private static final class RunningCreator implements AutoCloseable {
        final Process process;final Path log;
        RunningCreator(Path config,Path log)throws Exception{this.log=log;process=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"java.exe":"java").toString(),"-jar",System.getProperty("battlespades.applicationJar"),"--ugc-host","--config",config.toString(),"--control-stdin").redirectErrorStream(true).redirectOutput(log.toFile()).start();long deadline=System.nanoTime()+10_000_000_000L;try{while(!text().contains("World creator listening")){assertTrue(process.isAlive(),text());assertTrue(System.nanoTime()<deadline,"Creator JVM startup timed out: "+text());java.util.concurrent.locks.LockSupport.parkNanos(1_000_000);}}catch(Throwable error){close();throw error;}}
        String text()throws Exception{return Files.exists(log)?Files.readString(log):"";}
        void command(String command)throws Exception{process.getOutputStream().write((command+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));process.getOutputStream().flush();}
        void stop()throws Exception{command("shutdown");assertTrue(process.waitFor(10,java.util.concurrent.TimeUnit.SECONDS),text());assertEquals(0,process.exitValue(),text());assertTrue(text().contains("project saved"),text());}
        @Override public void close()throws java.io.IOException{if(process.isAlive()){process.destroy();try{if(!process.waitFor(3,java.util.concurrent.TimeUnit.SECONDS)){process.destroyForcibly();assertTrue(process.waitFor(3,java.util.concurrent.TimeUnit.SECONDS));}}catch(InterruptedException error){process.destroyForcibly();Thread.currentThread().interrupt();throw new java.io.IOException("Interrupted stopping creator test process",error);}}}
    }
